import ast
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
ROUTES = ROOT / "backend" / "modules" / "inteligencia_comercial" / "iscam_routes.py"


def openjson_sql():
    module = ast.parse(ROUTES.read_text(encoding="utf-8"))
    for node in module.body:
        if isinstance(node, ast.Assign):
            if any(isinstance(target, ast.Name) and target.id == "_OPENJSON_ITEMS" for target in node.targets):
                return ast.literal_eval(node.value)
    raise AssertionError("_OPENJSON_ITEMS no encontrado")


def test_invalid_json_uses_empty_array_before_openjson():
    sql = openjson_sql()
    assert "OPENJSON(CASE WHEN ISJSON(s.items) = 1 THEN s.items ELSE N'[]' END)" in sql
    assert "OPENJSON(s.items)" not in sql


def test_comandas_openjson_schema_is_preserved():
    sql = openjson_sql()
    assert "prod_id NVARCHAR(60) '$.id'" in sql
    assert "prod_name NVARCHAR(250) '$.name'" in sql
    assert "cantidad DECIMAL(18,3) '$.quantity'" in sql
    assert "precio DECIMAL(18,4) '$.price'" in sql
    assert "importe DECIMAL(18,4) '$.total'" in sql
